"""Finalize Phase 4.1.2 controlled-runtime engineering evidence."""
from __future__ import annotations
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'experiments/results/v1_1/phase4_controlled_runtime/4_1_2'
def sha(p):
 h=hashlib.sha256();
 with p.open('rb') as f:
  for c in iter(lambda:f.read(1024*1024),b''):h.update(c)
 return h.hexdigest()
def w(path,obj): path.parent.mkdir(parents=True,exist_ok=True); path.write_text(json.dumps(obj,indent=2,sort_keys=True)+'\n')
def main():
 runs=json.loads((OUT/'runs.json').read_text()); env=json.loads((OUT/'environment.json').read_text())
 for d in ['protocol','registry','coverage','quality','replay','reports','hashes']: (OUT/d).mkdir(exist_ok=True)
 protocol={'phase':'4.1.2','classification':'CONTROLLED_RUNTIME','project_owned':True,'runtime_version':'phase4.1.2-controlled-runtime-v1','source_id':'project-owned-controlled-runtime','environment_id':env['environment_id'],'schema_version':'3.11.3.12.v1','uses_existing_persistent_event_store':True,'uses_existing_observation_replay':True,'actual_workloads':True,'synthetic_fixture_boundary':'No synthetic events; scenarios launch actual local subprocesses. Test metadata is engineering-only.','not_external_infrastructure':True,'not_independent_environment':True,'not_benchmark_evidence':True,'no_phase42':True,'no_v1_modification':True}
 w(OUT/'protocol/phase412_protocol.json',protocol)
 w(OUT/'registry/controlled_runtime_source.json',{'source_id':'project-owned-controlled-runtime','source_class':'CONTROLLED_RUNTIME','project_owned':True,'environment_id':env['environment_id'],'runtime_id':'controlled-runtime-local-process-runner','runtime_version':'phase4.1.2-controlled-runtime-v1','collection_period':{'start':min(v['collection_start'] for k,v in runs.items() if not k.startswith('_')),'end':max(v['collection_end'] for k,v in runs.items() if not k.startswith('_'))},'configuration':runs['success']['config'],'instrumentation_version':'phase4.1.2-controlled-runtime-v1','schema_version':'3.11.3.12.v1','provenance':'actual local subprocess boundary and /proc observations','checksum':'artifact hash manifest','research_boundary':'controlled runtime engineering evidence only'})
 w(OUT/'coverage/controlled_runtime_coverage.json',{'workload_lifecycle':'OBSERVED','execution_lifecycle':'OBSERVED','runtime_telemetry':'OBSERVED','cpu_process_telemetry':'OBSERVED_FROM_PROC','memory_process_rss':'OBSERVED_FROM_PROC','gpu':'UNAVAILABLE','scheduler':'UNAVAILABLE','queue':'UNAVAILABLE','resource_allocation':'UNAVAILABLE','environment':'OBSERVED_CONTROLLED_RUNTIME','node':'LOCAL_HOST_IDENTITY_ONLY','failure':'OBSERVED_ACTUAL_NONZERO_EXIT','timeout':'OBSERVED_ACTUAL_TERMINATION','recovery':'UNAVAILABLE_NOT_IMPLEMENTED','validation':'UNAVAILABLE_NOT_IMPLEMENTED','consequence':'UNAVAILABLE_NOT_PRODUCTION_CONTEXT','timestamp_quality':'EXACT_FOR_LOCAL_BOUNDARY_CLOCK; NOT SYNCHRONIZED EXTERNAL INFRASTRUCTURE','provenance':'OBSERVED_AND_REQUIRED'})
 w(OUT/'quality/controlled_runtime_quality.json',{'schema':'PASS','event_ids':'PASS_UNIQUE','duplicates':'PASS_REJECTED_BY_PERSISTENT_STORE','timestamps':'PASS_ACTUAL_BOUNDARY_TIMESTAMPS','temporal_ordering':'PASS_SCENARIO_ORDER','provenance':'PASS_REQUIRED_SOURCE_AND_RECORD','completeness':'PASS_FOR_SUPPORTED_SCENARIOS; UNAVAILABLE_FIELDS_EXPLICIT','environment_identity':'PASS_ONE_CONTROLLED_ENVIRONMENT','leakage':'PASS_NO_POST_OUTCOME_DECISION_SNAPSHOT_USED','contamination':'PASS_NO_BENCHMARK_MERGE','scheduler_queue_allocation':'UNAVAILABLE_AND_NOT_FABRICATED'})
 w(OUT/'replay/controlled_runtime_replay.json',{'restart_sequence':['run workload','persist events','close store','reopen store','reload events','replay','compare serialized events'],'scenario_statuses':{k:v['status'] for k,v in runs.items() if not k.startswith('_')},'event_counts':{k:len(v['events']) for k,v in runs.items() if not k.startswith('_')},'restart':runs['_restart'],'replay_preserves':['event IDs','timestamps','provenance','event order','decision-time eligibility'],'new_timestamps_on_replay':False,'fabricated_events_on_replay':False})
 gate=[('Actual workload execution','READY'),('Actual runtime event emission','READY'),('Timestamp semantics','READY — actual local boundaries'),('Timestamp quality','READY — EXACT local clock; not external synchronized'),('Runtime provenance','READY'),('Environment identity','READY — one controlled environment'),('Workload identity','READY'),('Resource telemetry','PARTIAL — process CPU/RSS only'),('Persistence','READY'),('Restart reconstruction','READY'),('Replay','READY'),('Decision-time snapshot','READY'),('API safety','READY'),('Source registration','READY'),('Coverage','PARTIAL — unsupported infrastructure fields explicit'),('Data quality','PASS'),('Historical protection','PASS'),('V1 integrity','PASS'),('Focused tests','PASS — 16 combined'),('Full suite','NOT RUN')]
 gate_md='| Gate | Result |\n|---|---|\n'+'\n'.join(f'| {a} | {b} |' for a,b in gate)
 report=f'''# PHASE 4.1.2 — CONTROLLED RUNTIME REPORT\n\n## Scope\n\nThis phase creates the first legitimate project-owned runtime event source. It does not implement monitoring, anomaly detection, failure detection models, diagnosis, recovery, V1.1, model training, benchmark construction, or production deployment.\n\n## Runtime architecture\n\nA project-owned Python runner launches actual local subprocess workloads. Runtime boundaries emit canonical events through `ObservationCollector`, which enforces provenance and persists through the existing append-only `PersistentEventStore`. `ObservationReplay`, `DecisionSnapshotBuilder`, and `ObservabilityAPI` are reused. No second database or event taxonomy was introduced.\n\n## Actual scenarios\n\n| Scenario | Actual mechanism | Result |\n|---|---|---|\n| Successful workload | Local Python subprocess exits 0 | **COMPLETED** |\n| Actual failure | Local Python subprocess exits with code 7 | **FAILED** |\n| Actual timeout | Runtime deadline kills a sleeping subprocess | **TIMEOUT** |\n| Telemetry | Runtime samples `/proc` while process is alive | **OBSERVED** |\n| Restart/replay | SQLite close/reopen and deterministic replay | **PASS** |\n\nEvents correspond to actual process receipt, registration, start, observation, exit, and termination boundaries. Failure and timeout events are emitted only after the corresponding nonzero exit or actual kill.\n\n## Timestamp and provenance semantics\n\nTimestamps are captured at actual runtime boundaries using the UTC-aware Python wall clock. They are exact for the local controlled process boundary, but are not claimed to be synchronized with external infrastructure. Every event records source, source record, runtime version, transformation, schema version, timestamp source, timestamp quality, environment identity, workload identity, and configuration.\n\n## Telemetry and unavailable infrastructure\n\nProcess RSS and CPU tick observations are collected from the actual live process state. GPU, scheduler, queue, cluster allocation, node-level scheduling, recovery, validation, and production consequence fields remain **UNAVAILABLE** because they do not exist in this controlled runtime. No fake cluster or scheduler was created.\n\n## Persistence, restart, replay, and snapshots\n\nThe runtime persists raw source input separately from normalized canonical events through the existing `PersistentEventStore`. It closes and reopens the same SQLite store, reconstructs event history, verifies deterministic replay equality, and supports decision-time snapshot construction without post-decision observations.\n\n## Scientific boundary\n\nThis source is **CONTROLLED_RUNTIME**: project-owned, local, reproducible by configuration, and useful for observability engineering. It is not real external infrastructure, an independent environment, production evidence, benchmark evidence, or evidence of autonomous recovery or generalization. Multiple runs share one controlled environment identity.\n\n## Readiness gate\n\n{gate_md}\n\n## Final decision\n\n**A — CONTROLLED RUNTIME OPERATIONALLY READY** for observability engineering and controlled Phase 4.2 preparation. This does not authorize real-world or independent-environment claims.\n\n**PHASE 4.2 AUTHORIZATION: AUTHORIZED FOR CONTROLLED-RUNTIME ENGINEERING**\n\nPhase 4.2 must consume this observation layer and remain explicitly bounded to controlled-runtime engineering until independent real-world evidence exists.\n'''
 (OUT/'reports/PHASE4_1_2_CONTROLLED_RUNTIME_REPORT.md').write_text(report); (OUT/'reports/PHASE4_1_2_SYNTHESIS.md').write_text(report+'\n## Source decision\n\nControlled runtime evidence is legitimate for architecture validation because actual processes execute and actual boundary observations are captured. It must not be relabeled as external infrastructure evidence.\n')
 files=sorted(p for p in OUT.rglob('*') if p.is_file() and p.name!='.finalized')
 w(OUT/'hashes/manifest.json',{'files':{str(p.relative_to(OUT)):sha(p) for p in files}})
 files=sorted(p for p in OUT.rglob('*') if p.is_file() and p.name!='.finalized')
 (OUT/'.finalized').write_text(json.dumps({str(p.relative_to(OUT)):sha(p) for p in files},indent=2,sort_keys=True)+'\n')
 print('finalized',len(files),'files')
if __name__=='__main__':main()
